CREATE TABLE IF NOT EXISTS actors(actor_id TEXT PRIMARY KEY,display_name TEXT,category TEXT DEFAULT 'unknown',confidence DOUBLE PRECISION DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS investigations(investigation_id TEXT PRIMARY KEY,target TEXT NOT NULL,target_type TEXT NOT NULL,status TEXT NOT NULL,source TEXT,notes TEXT,actor_id TEXT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS identifiers(identifier_id TEXT PRIMARY KEY,investigation_id TEXT,actor_id TEXT,identifier_type TEXT NOT NULL,value TEXT NOT NULL,normalized_value TEXT,source TEXT,source_url TEXT,confidence DOUBLE PRECISION DEFAULT .5,first_seen TIMESTAMPTZ,last_seen TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS sources(source_id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT,source_type TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(evidence_id TEXT PRIMARY KEY,finding_id TEXT,source_id TEXT,evidence_type TEXT,source_url TEXT,excerpt TEXT,metadata JSONB,collected_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS findings(finding_id TEXT PRIMARY KEY,investigation_id TEXT,actor_id TEXT,finding_type TEXT NOT NULL,value TEXT NOT NULL,source TEXT,source_url TEXT,confidence DOUBLE PRECISION DEFAULT .5,metadata JSONB,first_seen TIMESTAMPTZ NOT NULL,last_seen TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS observations(observation_id TEXT PRIMARY KEY,investigation_id TEXT,actor_id TEXT,entity_type TEXT,entity_value TEXT,source_id TEXT,evidence_id TEXT,observed_at TIMESTAMPTZ NOT NULL,first_seen TIMESTAMPTZ,last_seen TIMESTAMPTZ,confidence DOUBLE PRECISION,metadata JSONB);
CREATE TABLE IF NOT EXISTS relationships(relationship_id TEXT PRIMARY KEY,investigation_id TEXT,from_type TEXT,from_value TEXT,relationship_type TEXT,to_type TEXT,to_value TEXT,source_id TEXT,evidence_id TEXT,confidence DOUBLE PRECISION,observed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS jobs(job_id TEXT PRIMARY KEY,investigation_id TEXT,job_type TEXT,status TEXT,progress DOUBLE PRECISION DEFAULT 0,payload JSONB,result_ref TEXT,error TEXT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS job_events(event_id TEXT PRIMARY KEY,job_id TEXT NOT NULL,event_type TEXT,message TEXT,progress DOUBLE PRECISION,payload JSONB,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS watchlist(watch_id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,interval_minutes INTEGER DEFAULT 60,enabled BOOLEAN DEFAULT TRUE,last_scan_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS alerts(alert_id TEXT PRIMARY KEY,actor_id TEXT,finding_id TEXT,alert_type TEXT,message TEXT,confidence DOUBLE PRECISION,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL);
